ALTER TABLE public.store_products DROP CONSTRAINT IF EXISTS store_products_subcategoria_valid;
ALTER TABLE public.store_products ADD CONSTRAINT store_products_subcategoria_valid CHECK (subcategoria IS NULL OR subcategoria IN ('Frutas','Verduras','Pollo y pavo','Res','Cerdo','Cordero y chivo','Pescado','Mariscos','Leche','Cremas','Huevos','Quesos','Yogur','Mantequilla','Pan de molde','Panecillos','Bagels y muffins','Pasteles y postres','Tortillas y arepas','Arroz y granos','Pastas','Enlatados','Salsas y condimentos','Aceites y especias','Para hornear','Desayuno','Papas y chips','Galletas saladas','Galletas dulces','Chocolates y dulces','Barras y frutos secos','Palomitas y pretzels','Carne seca','Agua y agua con gas','Refrescos','Jugos y néctares','Bebidas deportivas y energéticas','Té y café listos para tomar','Café y té (en grano, molido, cápsulas, bolsitas)','Bebidas latinas','Mezclas y bebidas en polvo','Agua de coco y bebidas vegetales'));